package org.jlinalg.cli;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class FavorAnnotationAuditTest {
    @TempDir Path directory;
    private int serial;
    private static final String SHA="0".repeat(64),OTHER="1".repeat(64),NULL="71557d1c8bac9bbe3cbec8d00bb223a2f372279827064095447e569fbf5a760a";
    private static final long RNA=0x7ff00000000007a2L,NAN=0x7ff8000000000000L;
    private static final FavorAnnotationAudit.Limits LIMITS=new FavorAnnotationAudit.Limits(1048576,32,100,10000,1048576,1048576,10000,1048576,1048576);
    private record Fixture(Path root,Path audit,Map<String,Object> metadata,List<Map<String,Object>> columns,
            Map<String,Map<String,Object>> files,List<String> headers,List<String> keys) { }
    private static byte[] chars(String... values)throws IOException {
        var out=new ByteArrayOutputStream();for(String value:values){byte[] bytes=value==null?new byte[0]:value.getBytes(StandardCharsets.UTF_8);out.write(ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(value==null?-1:bytes.length).array());out.write(bytes);}return out.toByteArray();
    }
    private static byte[] integers(int... values){var b=ByteBuffer.allocate(values.length*4).order(ByteOrder.LITTLE_ENDIAN);for(int x:values)b.putInt(x);return b.array();}
    private static byte[] doubles(long... bits){var b=ByteBuffer.allocate(bits.length*9).order(ByteOrder.LITTLE_ENDIAN);for(long value:bits)b.put((byte)(value==RNA?1:Double.isNaN(Double.longBitsToDouble(value))?2:0)).putLong(value);return b.array();}
    private Fixture fixture(boolean date)throws Exception {
        Path root=directory.resolve("fixture-"+(serial++));Files.createDirectory(root);for(String role:List.of("source","expected","stored"))Files.createDirectory(root.resolve(role));
        var keys=List.of("22-100-A-G","22-200-C-T","22-300-A-AT","22-400-AT-A","22-500-G-A");var headers=new ArrayList<>(List.of("VarInfo","variant_vcf","score","flag","label"));if(date)headers.add("date");
        var records=new ArrayList<Map<String,Object>>();var files=new LinkedHashMap<String,Map<String,Object>>();
        var source=new ArrayList<byte[]>();var projected=new ArrayList<byte[]>();source.add(chars(keys.toArray(String[]::new)));projected.add(source.get(0));source.add(chars(keys.get(0),keys.get(1),null,keys.get(3),keys.get(4)));projected.add(chars(keys.get(0),keys.get(1),"",keys.get(3),keys.get(4)));
        source.add(doubles(Double.doubleToRawLongBits(-0.0),Double.doubleToRawLongBits(0.1),Double.doubleToRawLongBits(Double.POSITIVE_INFINITY),RNA,NAN));projected.add(source.get(2));source.add(integers(1,0,Integer.MIN_VALUE,1,0));projected.add(source.get(3));source.add(chars("雪\tline\n\"quoted\"","",null,"last","literal"));projected.add(chars("雪\tline\n\"quoted\"","","","last","literal"));
        if(date){source.add(doubles(Double.doubleToRawLongBits(19723),Double.doubleToRawLongBits(19724),Double.doubleToRawLongBits(19725),Double.doubleToRawLongBits(19726),Double.doubleToRawLongBits(19727)));projected.add(source.get(5));}
        for(int i=0;i<headers.size();i++) {
            String type=i==2||i==5?"double":i==3?"logical":"character",base=type.equals("double")?"numeric":type;
            String kind=type.equals("double")?"FLOAT64_LE_TAGGED":type.equals("logical")?"LOGICAL_INT32_LE":"UTF8_LENGTH_INT32_LE_NA_NEGATIVE1";long missing=i==1||i==2||i==3||i==4?1:0;
            var c=new LinkedHashMap<String,Object>();c.put("index",i+1);c.put("name",headers.get(i));c.put("kind",kind);c.put("values",5);c.put("source_type",type);c.put("source_class",List.of(i==5?"Date":base));c.put("source_attributes",i==5?Map.of("class","Date"):null);c.put("source_attributes_sha256",i==5?OTHER:NULL);c.put("stored_type",type);c.put("stored_class",List.of(base));c.put("stored_attributes_sha256",NULL);c.put("source_attributes_lost",i==5);c.put("source_na",missing);c.put("source_nan",i==2?1:0);c.put("stored_na",type.equals("character")?0:missing);c.put("stored_nan",i==2?1:0);c.put("converted_character_na",type.equals("character")?missing:0);
            for(String role:List.of("source","expected","stored")) {
                String relative=role+"/c"+String.format(java.util.Locale.ROOT,"%04d",i+1)+".bin";byte[] raw=role.equals("source")?source.get(i):projected.get(i);Files.write(root.resolve(relative),raw);var f=new LinkedHashMap<String,Object>();f.put("path",relative);f.put("bytes",raw.length);f.put("sha256",AdmixtureInputs.digest(raw));c.put(role,f);files.put(role+":"+(i+1),f);
            }
            records.add(c);
        }
        var metadata=new LinkedHashMap<String,Object>();metadata.put("schema",FavorAnnotationAudit.SCHEMA);metadata.put("rows",5);metadata.put("columns",records);metadata.put("joined_csv_sha256",SHA);metadata.put("gds_sha256",SHA);metadata.put("original_frame_rows",0);metadata.put("warnings",date?List.of("Original Date attribute loss;required action:inspect provenance"):List.of());metadata.put("runtime",Map.of("R","R4.4.3","readr","2.2.0","gdsfmt","1.42.0","SeqArray","1.46.0","digest","0.6.39"));
        var f=new Fixture(root,root.resolve("audit.json"),metadata,records,files,headers,keys);save(f);return f;
    }
    private static void save(Fixture f)throws Exception {long bytes=0;for(var file:f.files().values())bytes+=((Number)file.get("bytes")).longValue();f.metadata().put("canonical_bytes",bytes);Files.writeString(f.audit(),RegenieRuntime.json(f.metadata()),StandardCharsets.UTF_8);}
    private static void replace(Fixture f,String role,int column,byte[] raw)throws Exception {var m=f.files().get(role+":"+column);Files.write(f.root().resolve((String)m.get("path")),raw);m.put("bytes",raw.length);m.put("sha256",AdmixtureInputs.digest(raw));}
    private static FavorAnnotationAudit.Prepared read(Fixture f,FavorAnnotationAudit.Limits limits)throws Exception {save(f);return direct(f,limits);}
    private static FavorAnnotationAudit.Prepared direct(Fixture f,FavorAnnotationAudit.Limits limits)throws Exception {return FavorAnnotationAudit.read(f.audit(),SHA,SHA,f.headers(),5,limits,()->{});}
    private FavorAnnotationAudit.Export export(Fixture f,FavorAnnotationAudit.Limits limits)throws Exception {return FavorAnnotationAudit.export(read(f,limits),f.keys(),directory.resolve("export-"+(serial++)),limits,()->{});}
    private static FavorAnnotationAudit.Limits limits(int meta,int cols,int rows,long cells,int scalar,long canonical,int block,long buffer,long output){return new FavorAnnotationAudit.Limits(meta,cols,rows,cells,scalar,canonical,block,buffer,output);}

    @Test void completeTypedValuesMissingnessAndSourceProjectionAreCounted()throws Exception {var f=fixture(false);var result=export(f,LIMITS);assertEquals(5,result.rows());assertEquals(5,result.columns());assertEquals(25,result.values());assertEquals(2,result.convertedCharacterNa());assertEquals(2,result.warnings().size());assertTrue(result.warnings().get(0).contains("ORIGINAL FRAME"));}
    @Test void readableQuotedTsvPreservesUnicodeDelimitersSignedZeroInfinityAndNan()throws Exception {var r=export(fixture(false),LIMITS);String values=Files.readString(r.valuesTsv());String states=Files.readString(r.statesTsv());assertTrue(values.contains("\"雪\tline\n\"\"quoted\"\"\""));assertTrue(values.contains("\"-0.0\""));assertTrue(values.contains("\"Infinity\""));assertTrue(values.contains("\"NaN\""));assertTrue(states.contains("\"NA\""));assertTrue(states.contains("source-character-NA-to-empty"));assertEquals(Files.size(r.valuesTsv())+Files.size(r.statesTsv())+Files.size(r.manifest())+Files.size(r.readme()),r.bytes());}
    @Test void DifferentBlockSizesProduceIdenticalCompleteExports()throws Exception {var f=fixture(false);var a=export(f,LIMITS);var b=export(f,limits(1048576,32,100,10000,1048576,1048576,5,1048576,1048576));assertEquals(a.valuesSha256(),b.valuesSha256());assertEquals(a.statesSha256(),b.statesSha256());}
    @Test void dateClassLossIsExplicitAndStoredValuesStayNumeric()throws Exception {var f=fixture(true);var p=read(f,LIMITS);assertEquals(List.of("Date"),p.columns().get(5).sourceClass());assertTrue(p.columns().get(5).attributesLost());var r=export(f,LIMITS);assertEquals(3,r.warnings().size());assertTrue(Files.readString(r.valuesTsv()).contains("\"19723.0\""));assertTrue(r.warnings().get(0).contains("do not restore"));}
    @Test void originalFrameMetadataAndCanonicalInputsAreNeverRepaired()throws Exception {var f=fixture(false);var p=read(f,LIMITS);String before=FollowupSupport.hash(f.audit());export(f,LIMITS);assertEquals(0,p.originalFrameRows());assertEquals(before,FollowupSupport.hash(f.audit()));p.verify(()->{});}
    @Test void nativeVariantKeyMismatchRejectsTheExport()throws Exception {var f=fixture(false);var keys=new ArrayList<>(f.keys());keys.set(4,"22-999-A-G");assertThrows(IOException.class,()->FavorAnnotationAudit.export(read(f,LIMITS),keys,directory.resolve("bad-keys"),LIMITS,()->{}));}
    @Test void alteredIeeeBitsCannotPassWithAnUpdatedExpectedStoredHash()throws Exception {var f=fixture(false);byte[] altered=Files.readAllBytes(f.root().resolve("stored/c0003.bin"));altered[1]^=1;replace(f,"stored",3,altered);replace(f,"expected",3,altered);assertThrows(IOException.class,()->export(f,LIMITS));}
    @Test void coherentButFalseMissingnessMetadataIsCaughtByTheActualValues()throws Exception {var f=fixture(false);f.columns().get(3).put("source_na",0);f.columns().get(3).put("stored_na",0);assertThrows(IOException.class,()->export(f,LIMITS));}
    @Test void invalidFloatingTagsAndLogicalCodesAreRejected()throws Exception {for(int column:List.of(3,4)){var f=fixture(false);for(String role:List.of("source","expected","stored")){byte[] raw=Files.readAllBytes(f.root().resolve(role+"/c000"+column+".bin"));raw[0]=7;replace(f,role,column,raw);}assertThrows(IOException.class,()->export(f,LIMITS));}}
    @Test void malformedUtf8IsNotRepairedDuringExport()throws Exception {var f=fixture(false);for(String role:List.of("source","expected","stored")){byte[] raw=Files.readAllBytes(f.root().resolve(role+"/c0005.bin"));raw[4]=(byte)0xff;replace(f,role,5,raw);}assertThrows(IOException.class,()->export(f,LIMITS));}
    @Test void truncatedAndExtraCanonicalValuesCannotAppearComplete()throws Exception {for(boolean extra:List.of(true,false)){var f=fixture(false);for(String role:List.of("source","expected","stored")){byte[] raw=Files.readAllBytes(f.root().resolve(role+"/c0003.bin"));replace(f,role,3,Arrays.copyOf(raw,raw.length+(extra?1:-1)));}assertThrows(IOException.class,()->export(f,LIMITS));}}
    @Test void canonicalChangeAfterAdmissionInvalidatesThePreparedAudit()throws Exception {var f=fixture(false);var p=read(f,LIMITS);Files.write(f.root().resolve("stored/c0001.bin"),new byte[]{0},java.nio.file.StandardOpenOption.APPEND);assertThrows(IOException.class,()->FavorAnnotationAudit.export(p,f.keys(),directory.resolve("changed"),LIMITS,()->{}));}
    @Test void protectedCsvGdsHashesAndExactHeaderOrderAreRequired()throws Exception {var f=fixture(false);assertThrows(IOException.class,()->FavorAnnotationAudit.read(f.audit(),OTHER,SHA,f.headers(),5,LIMITS,()->{}));var headers=new ArrayList<>(f.headers());java.util.Collections.swap(headers,3,4);assertThrows(IOException.class,()->FavorAnnotationAudit.read(f.audit(),SHA,SHA,headers,5,LIMITS,()->{}));}
    @Test void unknownMissingAndDuplicateMetadataFieldsAreRefused()throws Exception {var f=fixture(false);f.metadata().put("unknown",1);assertThrows(IOException.class,()->read(f,LIMITS));f.metadata().remove("unknown");f.metadata().remove("schema");assertThrows(IOException.class,()->read(f,LIMITS));save(f);Files.writeString(f.audit(),"{\"schema\":\"a\",\"schema\":\"b\"}");assertThrows(IOException.class,()->direct(f,LIMITS));}
    @Test void unknownScientificClassesAndStoredAttributesAreRefused()throws Exception {var f=fixture(false);f.columns().get(2).put("source_class",List.of("integer64"));assertThrows(IOException.class,()->read(f,LIMITS));f.columns().get(2).put("source_class",List.of("numeric"));f.columns().get(2).put("stored_attributes_sha256",OTHER);assertThrows(IOException.class,()->read(f,LIMITS));}
    @Test void dateTimeProvenanceCannotInventAnUnverifiedTimezone()throws Exception {var f=fixture(true);var c=f.columns().get(5);c.put("source_class",List.of("POSIXct","POSIXt"));c.put("source_attributes",Map.of("class",List.of("POSIXct","POSIXt"),"tzone","America/New_York"));assertThrows(IOException.class,()->read(f,LIMITS));}
    @Test void canonicalPathsMustMatchTheFixedOwnedColumnPlan()throws Exception {var f=fixture(false);f.files().get("stored:1").put("path","../outside.bin");assertThrows(IOException.class,()->read(f,LIMITS));}
    @Test void metadataPopulationScalarAndCanonicalByteCapacitiesAreEnforced()throws Exception {var f=fixture(false);for(var l:List.of(limits(10,32,100,10000,1048576,1048576,10000,1048576,1048576),limits(1048576,4,100,10000,1048576,1048576,10000,1048576,1048576),limits(1048576,32,4,10000,1048576,1048576,10000,1048576,1048576),limits(1048576,32,100,10,1048576,1048576,10000,1048576,1048576),limits(1048576,32,100,10000,1048576,10,10000,1048576,1048576)))assertThrows(IOException.class,()->read(f,l));assertThrows(IOException.class,()->export(f,limits(1048576,32,100,10000,1,1048576,10000,1048576,1048576)));}
    @Test void completeExportByteBufferAndBlockCapacitiesRejectWithoutTruncating()throws Exception {var f=fixture(false);for(var l:List.of(limits(1048576,32,100,10000,1048576,1048576,10000,1048576,10),limits(1048576,32,100,10000,1048576,1048576,10000,1024,1048576),limits(1048576,32,100,10000,1048576,1048576,4,1048576,1048576)))assertThrows(IOException.class,()->export(f,l));}
    @Test void anExistingOutputIsNeverOverwritten()throws Exception {var f=fixture(false);Path out=directory.resolve("existing");Files.createDirectory(out);Files.writeString(out.resolve("marker"),"retained");assertThrows(IOException.class,()->FavorAnnotationAudit.export(read(f,LIMITS),f.keys(),out,LIMITS,()->{}));assertEquals("retained",Files.readString(out.resolve("marker")));}
    @Test void cancellationInvalidatesReadAndExport()throws Exception {var f=fixture(false);assertThrows(IllegalStateException.class,()->FavorAnnotationAudit.read(f.audit(),SHA,SHA,f.headers(),5,LIMITS,()->{throw new IllegalStateException("cancelled");}));var p=read(f,LIMITS);assertThrows(IllegalStateException.class,()->FavorAnnotationAudit.export(p,f.keys(),directory.resolve("cancelled"),LIMITS,()->{throw new IllegalStateException("cancelled");}));}
    @Test void preparedMetadataAndWarningCollectionsAreImmutable()throws Exception {var p=read(fixture(true),LIMITS);assertThrows(UnsupportedOperationException.class,()->p.columns().clear());assertThrows(UnsupportedOperationException.class,()->p.columns().get(0).sourceClass().clear());assertThrows(UnsupportedOperationException.class,()->p.runtime().clear());assertThrows(UnsupportedOperationException.class,()->p.warnings().clear());}
    @Test void noIncompleteColumnOrMissingnessPopulationIsAdmitted()throws Exception {var f=fixture(false);f.columns().get(0).put("values",4);assertThrows(IOException.class,()->read(f,LIMITS));f.columns().get(0).put("values",5);f.columns().get(0).put("source_na",6);assertThrows(IOException.class,()->read(f,LIMITS));}
    @Test void invalidCapacitiesAreRefusedBeforeAnalysis() {assertThrows(IllegalArgumentException.class,()->limits(0,32,100,10000,1048576,1048576,10000,1048576,1048576));assertThrows(IllegalArgumentException.class,()->limits(1,1,100,10000,1048576,1048576,10000,1048576,1048576));assertThrows(IllegalArgumentException.class,()->limits(1,32,100,10000,16777217,1048576,10000,1048576,1048576));assertThrows(IllegalArgumentException.class,()->limits(1,32,100,10000,1,Long.MAX_VALUE,10000,1048576,1048576));}
    @Test void completedExportHasProminentWarningsAndScopedProvenanceManifest()throws Exception {var r=export(fixture(true),LIMITS);Map<?,?> m=AdmixtureInputs.json(r.manifest(),1048576);assertEquals("complete-scalar-export",m.get("status"));assertEquals(false,m.get("upstream_workflow_certified"));assertEquals(r.valuesSha256(),m.get("values_tsv_sha256"));String readme=Files.readString(r.readme());assertTrue(readme.contains("Required action:"));assertTrue(readme.contains("CHARACTER MISSINGNESS CONVERSION"));assertTrue(readme.contains("Complete scalar values can remain after a failed upstream command"));}
    @Test void failedScalarExportNeverPublishesItsCompletionManifest()throws Exception {var f=fixture(false);Path out=directory.resolve("failed-marker");var keys=new ArrayList<>(f.keys());keys.set(0,"bad");assertThrows(IOException.class,()->FavorAnnotationAudit.export(read(f,LIMITS),keys,out,LIMITS,()->{}));assertTrue(Files.exists(out.resolve("values.tsv")));assertFalse(Files.exists(out.resolve("export.json")));}
}
